SELECT post_id, feed_time, like_count
FROM post_feed_index
WHERE state = 'NORMAL'



            AND (like_count < #{cursor.likeCount}
                OR (like_count = #{cursor.likeCount} AND feed_time < #{cursor.feedTime})
                OR (like_count = #{cursor.likeCount} AND feed_time = #{cursor.feedTime}
                    AND post_id < #{cursor.postId}))


            AND (feed_time < #{cursor.feedTime}
                OR (feed_time = #{cursor.feedTime} AND post_id < #{cursor.postId}))



ORDER BY

